def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    divider_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != bg
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg
    ]

    def regions(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if d >= start:
                if start < d:
                    result.append(list(range(start, d)))
                start = d + 1
        if start < size:
            result.append(list(range(start, size)))
        return result

    row_regions = regions(h, divider_rows)
    col_regions = regions(w, divider_cols)
    out = [row[:] for row in grid]

    # Copy the contents of the first panel to every panel, keeping local positions.
    source = {}
    for i, r in enumerate(row_regions[0]):
        for j, c in enumerate(col_regions[0]):
            if grid[r][c] != bg:
                source[i, j] = grid[r][c]

    for rs in row_regions:
        for cs in col_regions:
            for (i, j), color in source.items():
                if i < len(rs) and j < len(cs):
                    out[rs[i]][cs[j]] = color

    return out
